namespace InvestmentCoPilot.Identity.Users;

/// <summary>
/// A local user, linked to one identity at the external provider by (<see cref="Issuer"/>, <see cref="Subject"/>).
/// <see cref="Id"/> is generated by the application, so it stays the same if the provider changes.
/// </summary>
internal sealed class User
{
    public const int MaxIssuerLength = 512;
    public const int MaxSubjectLength = 255;
    public const int MaxEmailLength = 320;
    public const int MaxDisplayNameLength = 200;

    public Guid Id { get; init; }

    public required string Issuer { get; init; }

    public required string Subject { get; init; }

    public string? Email { get; set; }

    public string? DisplayName { get; set; }

    public DateTimeOffset CreatedAt { get; init; }
}
